/* Authored VN scenes and typed outcomes; no DOM/network. */
(function(g){'use strict';const copy=x=>JSON.parse(JSON.stringify(x)),need=(v,m)=>{if(!v)throw Error(m);},id=v=>{need(typeof v==='string'&&/^[a-zA-Z0-9_-]{1,80}$/.test(v),'ID อีเวนต์/บท/เควสไม่ถูกต้อง');return v;},text=(v,n=4000)=>{need(typeof v==='string'&&v.length<=n,'ข้อความอีเวนต์ยาวเกินกำหนด');return v;};
const kinds=['item','dropItem','weapon','armor','helmet','boots','accessory'];
function image(v=''){text(v,1100000);need(!v||/^(https?:\/\/|data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=]+$)/i.test(v),'รูปอีเวนต์ต้องเป็น PNG JPG WebP GIF หรือลิงก์ http/https');return v;}
function combat(v){if(!v)return null;need(Number.isInteger(v.enemyCount??1)&&(v.enemyCount??1)>=1&&(v.enemyCount??1)<=5&&Number.isInteger(v.minutes??0)&&(v.minutes??0)>=0&&(v.minutes??0)<=10080,'จำนวนศัตรู/เวลาต่อสู้ไม่ถูกต้อง');return {kind:'combat',sceneId:text(v.sceneId||'',150),monsterId:v.monsterId?id(v.monsterId):'',enemyCount:v.enemyCount??1,allowRetreat:v.allowRetreat!==false,minutes:v.minutes??0,winNode:v.winNode?id(v.winNode):'',lossNode:v.lossNode?id(v.lossNode):'',retreatNode:v.retreatNode?id(v.retreatNode):''};}
function choice(ch){need(ch&&ch.label?.trim()&&Number.isSafeInteger(ch.goldDelta??0)&&Math.abs(ch.goldDelta??0)<=1000000&&Number.isInteger(ch.energyDelta??0)&&Math.abs(ch.energyDelta??0)<=100&&Number.isInteger(ch.minutes??0)&&(ch.minutes??0)>=0&&(ch.minutes??0)<=10080,'ผลตัวเลือกไม่ถูกต้อง');need(Array.isArray(ch.items||[])&&(ch.items||[]).length<=12,'ให้ไอเท็มได้ไม่เกิน 12 ชนิดต่อข้อ');const items=(ch.items||[]).map(x=>{need(kinds.includes(x.kind)&&Number.isInteger(x.quantity)&&x.quantity>=1&&x.quantity<=99,'ชนิด/จำนวนไอเท็มไม่ถูกต้อง');return {kind:x.kind,id:id(x.id),quantity:x.quantity};});let quest=null;if(ch.quest){const q=ch.quest;need(q.title?.trim()&&['active','completed','failed'].includes(q.status),'ระบุชื่อ/สถานะเควส');quest={id:id(q.id),title:text(q.title,150),description:text(q.description||'',2000),status:q.status};}const out={id:id(ch.id),label:text(ch.label.trim(),150),text:text(ch.text||'',2000),goldDelta:ch.goldDelta??0,energyDelta:ch.energyDelta??0,minutes:ch.minutes??0,items,quest,nextNode:ch.nextNode?id(ch.nextNode):'',nextEventId:ch.nextEventId?id(ch.nextEventId):'',combat:combat(ch.combat)};need([!!out.nextNode,!!out.nextEventId,!!out.combat].filter(Boolean).length<=1,'เลือกปลายทางเดียว: บทถัดไป / อีเวนต์เสริม / ต่อสู้');return out;}
function validate(v){if(!v)return null;need(Array.isArray(v.nodes)&&v.nodes.length>=1&&v.nodes.length<=60,'อีเวนต์ต้องมี 1–60 บท');const out={npcId:v.npcId?id(v.npcId):'',background:image(v.background||''),bgmId:text(v.bgmId||'',150),startNode:id(v.startNode),nodes:v.nodes.map(n=>{need(n&&Array.isArray(n.choices)&&n.choices.length>=1&&n.choices.length<=6,'แต่ละบทต้องมี 1–6 ตัวเลือก');const choices=n.choices.map(choice);need(new Set(choices.map(c=>c.id)).size===choices.length&&choices.some(c=>c.goldDelta>=0),'ID ตัวเลือกซ้ำ หรือต้องมีทางไม่เสียเหรียญ');return {id:id(n.id),npcId:n.npcId?id(n.npcId):'',background:image(n.background||''),text:text(n.text||''),choices};})};const nodes=new Map(out.nodes.map(n=>[n.id,n]));need(nodes.size===out.nodes.length&&nodes.has(out.startNode),'ID บทซ้ำหรือไม่พบบทเริ่มต้น');for(const n of out.nodes)for(const c of n.choices)for(const target of [c.nextNode,c.combat?.winNode,c.combat?.lossNode,c.combat?.retreatNode].filter(Boolean))need(nodes.has(target),'ไม่พบบทปลายทาง '+target);const visiting=new Set(),done=new Set();function visit(key){need(!visiting.has(key),'บทสนทนาวนซ้ำ กรุณาเชื่อมไปข้างหน้าหรือจบอีเวนต์');if(done.has(key))return;visiting.add(key);for(const c of nodes.get(key).choices)for(const next of [c.nextNode,c.combat?.winNode,c.combat?.lossNode,c.combat?.retreatNode].filter(Boolean))visit(next);visiting.delete(key);done.add(key);}for(const key of nodes.keys())visit(key);return out;}
function journal(v){if(v===undefined)return {v:1,quests:[],stories:[]};need(v&&v.v===1&&Array.isArray(v.quests)&&v.quests.length<=500&&Array.isArray(v.stories)&&v.stories.length<=100,'สมุดเควส/เรื่องราวไม่ถูกต้อง');const quests=v.quests.map(q=>{need(['active','completed','failed'].includes(q.status),'สถานะเควสไม่ถูกต้อง');return {id:id(q.id),title:text(q.title,150),description:text(q.description||'',2000),status:q.status};});need(new Set(quests.map(q=>q.id)).size===quests.length,'ID เควสซ้ำ');return {v:1,quests,stories:v.stories.map(x=>({eventId:id(x.eventId),nodeId:id(x.nodeId),text:text(x.text,2000)}))};}
function apply(s,p,choiceId,rows,W){const ev=p.event,n=ev.novel.nodes.find(n=>n.id===(p.nodeId||ev.novel.startNode));need(n,'ไม่พบบทสนทนา');const ch=n.choices.find(c=>c.id===choiceId);need(ch,'ไม่พบตัวเลือก');need(Number.isSafeInteger(s.gold+ch.goldDelta)&&s.gold+ch.goldDelta>=0&&s.gold+ch.goldDelta<=1e9,'เหรียญไม่พอหรือเกินขอบเขต');const E=g.DecideCatalogEconomy||(typeof require==='function'?require('./catalog-economy'):null),inv=E.validate(s.catalogInventory);for(const grant of ch.items){const item=rows.find(r=>r.kind===grant.kind&&r.id===grant.id&&r.enabled!==false);need(item,'ไม่พบไอเท็มที่เปิดใช้ '+grant.id);for(let i=0;i<grant.quantity;i++)if(['item','dropItem'].includes(grant.kind))inv.items.push(item.name);else inv.gearStash.push({refType:grant.kind,name:item.name});}s.catalogInventory=E.validate(inv);W.clock(s,ch.minutes);s.overworld.journey.eventMinutes+=ch.minutes;s.gold+=ch.goldDelta;s.energy=Math.max(0,Math.min(100,s.energy+ch.energyDelta));const book=journal(s.eventJournal);if(ch.quest){const at=book.quests.findIndex(q=>q.id===ch.quest.id);if(at<0){need(book.quests.length<500,'สมุดเควสเต็ม');book.quests.push(copy(ch.quest));}else book.quests[at]=copy(ch.quest);}book.stories.unshift({eventId:ev.id,nodeId:n.id,text:ch.text||ch.label});book.stories=book.stories.slice(0,100);s.eventJournal=book;W.note(s,ev.name+' • '+ch.label+(ch.text?' • '+ch.text:''));if(ch.combat){p.combat=copy(ch.combat);return {complete:false};}if(ch.nextNode){p.nodeId=ch.nextNode;return {complete:false};}return {complete:true,link:ch.nextEventId};}
function refs(events,rows,scenes,presets){const enabled=events.filter(e=>e.enabled);for(const e of enabled){const novel=e.novel;if(novel){for(const npc of [novel.npcId,...novel.nodes.map(n=>n.npcId)].filter(Boolean))need(rows.some(r=>r.kind==='npc'&&r.id===npc&&r.enabled!==false),'อีเวนต์ '+e.id+' ไม่พบ NPC '+npc);for(const n of novel.nodes)for(const c of n.choices){for(const item of c.items)need(rows.some(r=>r.kind===item.kind&&r.id===item.id&&r.enabled!==false),'ไม่พบไอเท็ม '+item.id);if(c.nextEventId)need(enabled.some(x=>x.id===c.nextEventId),'ไม่พบอีเวนต์เสริมที่เปิดใช้ '+c.nextEventId);}}
for(const b of [e.kind==='combat'?e:null,...(novel?.nodes.flatMap(n=>n.choices.map(c=>c.combat))||[])].filter(Boolean)){if(b.monsterId)need(rows.some(r=>r.kind==='monster'&&r.id===b.monsterId&&r.enabled!==false),'ไม่พบมอนสเตอร์ '+b.monsterId);if(b.sceneId)need(b.sceneId.startsWith('preset:')?presets.some(x=>x.id===b.sceneId.slice(7)):scenes.some(x=>x.id===b.sceneId),'ไม่พบฉากต่อสู้ '+b.sceneId);}}
const checked=new Set();const visit=(e,path)=>{need(!path.has(e.id),'อีเวนต์เสริมวนซ้ำที่ '+e.id);if(checked.has(e.id))return;const next=new Set(path).add(e.id);for(const id of e.novel?.nodes.flatMap(n=>n.choices.map(c=>c.nextEventId)).filter(Boolean)||[])visit(enabled.find(e=>e.id===id),next);checked.add(e.id);};for(const e of enabled)visit(e,new Set());}
const api={id,image,combat,choice,validate,journal,apply,refs,kinds};g.DecideEventStory=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
